(5477120, 787886, 56502, '<td valign="top">Certainly meets the challenge. <br/>The way you positioned Waldo according to the thirds rule shows the hand of a true master! Nevertheless the picture suffers somewhat from the lack of detail. <br/>But maybe that''s just my monitor not being calibrated.</td>', 'Certainly meets the challenge. The way you positioned Waldo according to the thirds rule shows the hand of a true master! Nevertheless the picture suffers somewhat from the lack of detail. But maybe that''s just my monitor not being calibrated.', '2009-05-08 16:28:57.000000', NULL, 1),
(5477154, 788661, 56502, '<td valign="top">Great colors and detail.</td>', 'Great colors and detail.', '2009-05-08 16:55:15.000000', NULL, 1),
(5477178, 788742, 84997, '<td valign="top">That is a really nice picture. I love the detail.</td>', 'That is a really nice picture. I love the detail.', '2009-05-08 17:10:42.000000', NULL, 1),
(5477179, 786626, 104198, '<td valign="top">Grainy</td>', 'Grainy', '2009-05-08 17:12:27.000000', NULL, 1),
(5477186, 787372, 84997, '<td valign="top">I wish there was more focus on the buildings.</td>', 'I wish there was more focus on the buildings.', '2009-05-08 17:16:48.000000', NULL, 1),
(5477190, 788254, 84997, '<td valign="top">This is a great picture.</td>', 'This is a great picture.', '2009-05-08 17:18:53.000000', NULL, 1),
(5477192, 787303, 84997, '<td valign="top">Great contrast.</td>', 'Great contrast.', '2009-05-08 17:20:15.000000', NULL, 1),
(5477193, 788202, 84997, '<td valign="top">Would have liked it better if the light wasn''t so bright in the middle.</td>', 'Would have liked it better if the light wasn''t so bright in the middle.', '2009-05-08 17:21:17.000000', NULL, 1),
