(5486109, 787660, 50695, '<td valign="top">I love the idea of a foreground silhouette cutting a shape out of the background. One of my top picks.</td>', 'I love the idea of a foreground silhouette cutting a shape out of the background. One of my top picks.', '2009-05-14 14:22:29.000000', NULL, 0),
(5486112, 788294, 50695, '<td valign="top">very good. a sophisticated composition.</td>', 'very good. a sophisticated composition.', '2009-05-14 14:23:45.000000', NULL, 0),
(5486301, 788502, 30982, '<td valign="top">I love the way the processing brought out the subtle color and enriched them.  Makes for an intriguing abstract!</td>', 'I love the way the processing brought out the subtle color and enriched them.  Makes for an intriguing abstract!', '2009-05-14 16:28:31.000000', NULL, 0),
(5486885, 788458, 67697, '<td valign="top">The lighting in this is amazing.  She is so beautiful.  Never would have guessed she was 14.  Congrats on the ribbon!</td>', 'The lighting in this is amazing.  She is so beautiful.  Never would have guessed she was 14.  Congrats on the ribbon!', '2009-05-14 21:37:13.000000', NULL, 0),
(5487215, 787731, 96881, '<td valign="top">I like the effect you have achieved here.  however, with some extra Post Processing, you could have made this sunrise really stand out.  The colours are quite light and subtle in this image.  By adding some additional contrast, both globally, and then to selected colours (yellow/red) you can make the sky glow much more, with richer tones.  Added to this, adjusting the midtone levels slightly darker then will darken that area of the image, which is the sky area in this photo, helping richen the colours.  These small changes then add significantly to the photo.  These clouds are then closer to red, and lighter ones orange, ad the blue is darker..........<br/> <br/>It is a shame the large bank of clouds is in the upper part of the shot, but nothing you can do about that.  in terms of composition, the tree could have been better sitting on a line of third, therefore with more space included on the left hand side of the picture, making it stand more clearly as the subject<br/> <br/>Hope this helps  :)</td>', 'I like the effect you have achieved here.  however, with some extra Post Processing, you could have made this sunrise really stand out.  The colours are quite light and subtle in this image.  By adding some additional contrast, both globally, and then to selected colours (yellow/red) you can make the sky glow much more, with richer tones.  Added to this, adjusting the midtone levels slightly darker then will darken that area of the image, which is the sky area in this photo, helping richen the colours.  These small changes then add significantly to the photo.  These clouds are then closer to red, and lighter ones orange, ad the blue is darker.......... It is a shame the large bank of clouds is in the upper part of the shot, but nothing you can do about that.  in terms of composition, the tree could have been better sitting on a line of third, therefore with more space included on the left hand side of the picture, making it stand more clearly as the subject Hope this helps  :)', '2009-05-15 01:41:13.000000', NULL, 0),
(5487322, 787480, 22459, '<td valign="top">very creative work and a great take on the challenge. good to see you trying different techniques.</td>', 'very creative work and a great take on the challenge. good to see you trying different techniques.', '2009-05-15 03:09:09.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5488201, 787538, 39057, '<td valign="top">The markings are correct enough for us here at DPC !  The three stars in the bottom polygon (not the ones that form the belt) make up his sword. These are the stars that are going from upper right to lower left in the middle of the bottom polygon. The top right star is very dim. If I recall...it is not a star at all but the Orion Nebula...which IMO you can just about make out the "purplish" tint in your photo.</td>', 'The markings are correct enough for us here at DPC !  The three stars in the bottom polygon (not the ones that form the belt) make up his sword. These are the stars that are going from upper right to lower left in the middle of the bottom polygon. The top right star is very dim. If I recall...it is not a star at all but the Orion Nebula...which IMO you can just about make out the "purplish" tint in your photo.', '2009-05-15 15:35:23.000000', NULL, 0),
(5488313, 787651, 16106, '<td valign="top">This is such a silken subtle image, it got my personal top finish.</td>', 'This is such a silken subtle image, it got my personal top finish.', '2009-05-15 16:43:22.000000', NULL, 0),
(5488353, 787538, 67697, '<td valign="top">This is so beautiful.  I wish I could capture skies like this.  I remember having to do a gradeschool report on Orion so it is one of the first things I recognize in the sky.  Congrats on the blue!</td>', 'This is so beautiful.  I wish I could capture skies like this.  I remember having to do a gradeschool report on Orion so it is one of the first things I recognize in the sky.  Congrats on the blue!', '2009-05-15 17:08:37.000000', NULL, 0),
(5488645, 787538, 20608, '<td valign="top">many grats on the blue</td>', 'many grats on the blue', '2009-05-15 20:10:54.000000', NULL, 0),
(5488646, 787894, 20608, '<td valign="top">great red shot</td>', 'great red shot', '2009-05-15 20:11:14.000000', NULL, 0),
(5488786, 788264, 31637, '<td valign="top">Very meaningful portrait, reminding us that we are better off being ignorant, but then again, I''m a science guy. I love the composition, very artistic and framed well.  It''s ok to focus on the hand in this case, perhaps your aperture was a bit wide?</td>', 'Very meaningful portrait, reminding us that we are better off being ignorant, but then again, I''m a science guy. I love the composition, very artistic and framed well.  It''s ok to focus on the hand in this case, perhaps your aperture was a bit wide?', '2009-05-15 23:33:28.000000', NULL, 0),
(5488929, 788709, 97225, '<td valign="top">That is an original image, and I love the warm glowing light.</td>', 'That is an original image, and I love the warm glowing light.', '2009-05-16 01:33:46.000000', NULL, 0),
